def can_make_abc(s):
    # Check if the string is already "abc"
    if s == "abc":
        return "YES"

    # Check if the string can be made "abc" by swapping two characters
    # We need to check all possible pairs of characters
    for i in range(3):
        for j in range(i+1, 3):
            if s[i] == s[j]:
                continue
            # Swap the characters at positions i and j
            s = s[:i] + s[j] + s[i+1:j] + s[i] + s[j+1:]
            if s == "abc":
                return "YES"

    return "NO"

