def maximumOr(nums, k):
    nums.sort(reverse=True)
    for i in range(k):
        nums[i] *= 2
    return nums[0] | nums[1] | ... | nums[len(nums) - 1]

def count_good_integers(num1, num2, min_sum, max_sum):
    MOD = 10**9 + 7

    def digit_sum(x):
        return sum(int(digit) for digit in str(x))

    def count_good_integers_helper(num1, num2, min_sum, max_sum):
        if num1 > num2:
            return 0

        count = 0
        for x in range(int(num1), int(num2) + 1):
            if min_sum <= digit_sum(x) <= max_sum:
                count += 1
        return count

    return count_good_integers_helper(num1, num2, min_sum, max_sum) % MOD

