def maxSumQueries(nums1, nums2, queries):
    n = len(nums1)
    max_sum = [-1] * n

    # Precompute the maximum sum for each index
    for i in range(n):
        max_sum[i] = max(nums1[i] + nums2[i], max_sum[i-1] if i > 0 else -1)

    # Process each query
    for x, y in queries:
        if x >= max_sum[0] and y >= max_sum[0]:
            max_sum[0] = max(max_sum[0], x + y)
        elif x >= max_sum[0]:
            max_sum[0] = max(max_sum[0], x + max_sum[0])
        elif y >= max_sum[0]:
            max_sum[0] = max(max_sum[0], max_sum[0] + y)
        else:
            max_sum[0] = -1

    return max_sum

def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1
    for i in range(n):
        for j in range(n):
            if i == 0:
                dp[i][j] = 1
            else:
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % MOD
    return dp[n-1][n-1]

def maxJumps(nums, target):
    n = len(nums)
    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        for j in range(i):
            if abs(nums[i] - nums[j]) <= target:
                dp[i] = max(dp[i], dp[j] + 1)
    return dp[n-1] if dp[n-1] > 0 else -1

def maxNonDecreasingLength(nums1, nums2):
    n = len(nums1)
    dp = [1] * n
    for i in range(1, n):
        if nums1[i] >= nums1[i-1]:
            dp[i] = dp[i-1] + 1
        if nums2[i] >= nums2[i-1]:
            dp[i] = max(dp[i], dp[i-1] + 1)
    return max(dp)

def prime_pairs(n):
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5) + 1):
            if x % i == 0:
                return False
        return True

    prime_pairs = []
    for x in range(2, n//2 + 1):
        y = n - x
        if is_prime(x) and is_prime(y):
            prime_pairs.append([x, y])
    return sorted(prime_pairs)

def minChanges(s: str, k: int) -> int:
    n = len(s)
    dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for l in range(i):
                dp[i][j] = min(dp[i][j], dp[l][j - 1] + (s[l:i] == s[l:i][::-1]))

    return dp[n][k]

def split_strings(words, separator):
