def count_ways(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            dp[i] = (dp[i] + dp[i - j**x]) % MOD
    return dp[n]

def minimum_index(nums):
    def find_dominant(arr):
        freq = {}
        for num in arr:
            if num in freq:
                freq[num] += 1
            else:
                freq[num] = 1
        return max(freq.values())

    n = len(nums)
    for i in range(n - 1):
        left_freq = find_dominant(nums[:i+1])
        right_freq = find_dominant(nums[i+1:])
        if left_freq * 2 > n and right_freq * 2 > n:
            return i
    return -1

def maxBeauty(nums, k):
    nums.sort()
    left, right = 0, len(nums) - 1
    while left < right:
        if nums[left] - k == nums[right]:
            left += 1
            right -= 1
        else:
            right -= 1
    return right

def max_groups(usageLimits):
