def countSteppingNumbers(low: str, high: str) -> int:
    def dfs(num: str, prev: int, is_limit: bool, is_leading_zero: bool) -> int:
        if len(num) == len(high):
            return 1

        count = 0
        for i in range(len(num)):
            if is_leading_zero and int(num[i]) == 0:
                count += dfs(num[:i] + str(prev + 1), prev, is_limit, True)
            elif int(num[i]) == prev + 1:
                count += dfs(num[:i] + str(prev + 1), prev, is_limit, False)
            else:
                count += dfs(num[:i] + str(prev), prev, is_limit, False)

        return count % MOD

    return dfs(str(int(low)), -1, True, True)

def minTime(nums1, nums2, x):
    total_sum = sum(nums1)
    if total_sum <= x:
        return 0

    for i in range(len(nums1)):
        if nums1[i] > 0:
            nums1[i] -= nums2[i]
            if total_sum - nums1[i] <= x:
                return i + 1

    return -1

def countPairs(coordinates, k):
