def maxSumAlmostUniqueSubarray(nums, m, k):
    max_sum = 0
    current_sum = 0
    distinct_count = 0
    start = 0

    for end in range(len(nums)):
        if nums[end] not in nums[start:end+1]:
            distinct_count += 1
        current_sum += nums[end]

        while distinct_count >= m:
            max_sum = max(max_sum, current_sum)
            if nums[start] not in nums[start+1:end+1]:
                distinct_count -= 1
            current_sum -= nums[start]
            start += 1

    return max_sum

def minOperations(nums, target):
    dp = [float('inf')] * (target + 1)
    dp[0] = 0
    for num in nums:
        for i in range(target, num - 1, -1):
            dp[i] = min(dp[i], dp[i - num] + 1)
    return dp[target] if dp[target] != float('inf') else -1

def productMatrix(grid):
    n, m = len(grid), len(grid[0])
    mod = 12345
    result = [[0]*m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            product = 1
            for k in range(n):
                product = (product * grid[k][j]) % mod
            result[i][j] = product

    return result

def max_function_value(receiver, k):
    n = len(receiver)
    max_value = 0
    for i in range(n):
        current_value = i
        for _ in range(k):
            current_value += receiver[current_value]
        max_value = max(max_value, current_value)
    return max_value

import math

def max_element_sum(nums):
    n = len(nums)
    max_sum = 0
    for i in range(1, n+1):
        product = 1
        for j in range(i, n+1, i):
            product *= nums[j-1]
        if math.isqrt(product) ** 2 == product:
            max_sum = max(max_sum, i)
    return max_sum

