    left, right = 0, len(nums) - 1
    while left < right:
        if nums[left] < nums[right]:
            left += 1
        else:
            right -= 1
    return right

def countSubMultisets(nums, l, r):
    MOD = 10**9 + 7

    # Count the frequency of each number in nums
    freq = {}
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the dp array
    dp = [0] * (r + 1)
    dp[0] = 1

    # Iterate over the frequency of each number
    for num, count in freq.items():
        # Update the dp array
        for i in range(r, num - 1, -1):
            dp[i] = (dp[i] + dp[i - num]) % MOD

    # Return the count of sub-multisets with sum in the range [l, r]
    return dp[l]

def maximumSumOfHeights(maxHeights):
    n = len(maxHeights)
    heights = [0] * n
    heights[0] = maxHeights[0]
    for i in range(1, n):
        heights[i] = min(maxHeights[i], heights[i-1] + 1)

    left_sum = [0] * n
    left_sum[0] = heights[0]
    for i in range(1, n):
        left_sum[i] = left_sum[i-1] + heights[i]

    right_sum = [0] * n
    right_sum[n-1] = heights[n-1]
    for i in range(n-2, -1, -1):
        right_sum[i] = right_sum[i+1] + heights[i]

    return max(left_sum[-1], right_sum[0])

def shortest_subarray(nums, target):
    total_sum = sum(nums)
    if total_sum % target != 0:
        return -1

    target_sum = total_sum // target
    current_sum = 0
    min_length = float('inf')
    start = 0

    for end in range(len(nums)):
        current_sum += nums[end]

        while current_sum >= target_sum:
            if current_sum == target_sum:
                min_length = min(min_length, end - start + 1)
            current_sum -= nums[start]
            start += 1

    return min_length if min_length != float('inf') else -1

def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    nums.sort(reverse=True)

    for i in range(k):
        nums[i] = (nums[i] & nums[i+1]) | (nums[i] & nums[i+1])

    return sum(x**2 for x in nums[:k]) % MOD

def minSum(nums1, nums2):
    sum1 = sum(nums1)
    sum2 = sum(nums2)

    if sum1 == sum2:
        return sum1

    if sum1 < sum2:
        return -1

    if sum2 < sum1:
        return -1

    if sum1 == sum2:
        return sum1

    if sum1 < sum2:
        return sum1 + sum2 - sum1

    if sum2 < sum1:
