def min_operations(nums1, nums2):
    n = len(nums1)
    max1 = max(nums1)
    max2 = max(nums2)

    if nums1[-1] != max1 or nums2[-1] != max2:
        return -1

    operations = 0
    for i in range(n-1):
        if nums1[i] != max1 or nums2[i] != max2:
            operations += 1
            if nums1[i] != max1 and nums2[i] != max2:
                return -1
            if nums1[i] != max1 and nums2[i] == max2:
                return -1
            if nums2[i] != max2 and nums1[i] == max1:
                return -1
            if nums2[i] != max2 and nums1[i] == max1:
                return -1

    return operations

def maxFrequencyScore(nums, k):
    nums.sort()
    left = 0
    max_freq = 0
    for right in range(len(nums)):
        while nums[right] - nums[left] > 2 * k:
            left += 1
        max_freq = max(max_freq, right - left + 1)
    return max_freq

def canMakePalindrome(s, queries):
    n = len(s)
    half = n // 2

    def can_make_palindrome(a, b, c, d):
        # Check if the substring s[a:b] can be rearranged to make s a palindrome
        if b - a + 1 > 1:
            return s[a:b] == s[b:a][::-1]

        # Check if the substring s[c:d] can be rearranged to make s a palindrome
        if d - c + 1 > 1:
            return s[c:d] == s[d:c][::-1]

        return False

    answer = []
    for a, b, c, d in queries:
        if can_make_palindrome(a, b, c, d):
            answer.append(True)
        else:
            answer.append(False)

    return answer

def count_good_partitions(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        dp[i] = dp[i - 1]
        for j in range(i - 1, -1, -1):
            if nums[j] == nums[i - 1]:
                dp[i] = (dp[i] + dp[j]) % MOD
    return dp[n]

def subarrays(nums, k):
