def lexicographically_smallest_array(nums, limit):
    nums.sort()
    for i in range(len(nums) - 1):
        if nums[i + 1] - nums[i] > limit:
            nums[i], nums[i + 1] = nums[i + 1], nums[i]
    return nums

def longest_good_subarray(nums, k):
    max_length = 0
    current_length = 0

    for num in nums:
        if num == nums[0]:
            current_length += 1
        else:
            if current_length <= k:
                current_length += 1
            else:
                max_length = max(max_length, current_length)
                current_length = 1

    if current_length <= k:
        max_length = max(max_length, current_length)

    return max_length

def minCoins(coins, target):
    coins.sort()
    dp = [float('inf')] * (target + 1)
    dp[0] = 0
    for coin in coins:
        for i in range(coin, target + 1):
            dp[i] = min(dp[i], dp[i - coin] + 1)
    return target - dp[target]

def minCost(source, target, original, changed, cost):
    n = len(source)
    dp = [[float('inf')] * n for _ in range(n)]
    dp[0][0] = 0

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            if i > 0 and j > 0 and original[i-1] == original[j-1] and changed[i-1] == changed[j-1]:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1] + cost[i-1])
            if i > 0 and j > 0 and original[i-1] == changed[j-1] and changed[i-1] == original[j-1]:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1] + cost[i-1])
            if i > 0 and j > 0 and original[i-1] == changed[j-1] and changed[i-1] == changed[j-1]:
                dp[i][j] = min(dp[i][j], dp[i-1][j-1] + cost[i-1])

    return dp[n-1][n-1] if dp[n-1][n-1] != float('inf') else -1

def min_length(nums):
    nums.sort()
    for i in range(len(nums) - 1):
        if nums[i] > nums[i + 1]:
            nums[i] %= nums[i + 1]
            nums.pop(i + 1)
            nums.pop(i)
    return len(nums)

def minBitwiseOR(nums, k):
    nums.sort()
    n = len(nums)
    for i in range(n):
        if k == 0:
            break
        if i > 0:
            nums[i] &= nums[i - 1]
            k -= 1
        else:
            break
    return nums[0] | nums[1]

def largestPerimeter(nums):
    nums.sort(reverse=True)
    if len(nums) < 3:
        return -1
    else:
        return sum(nums[:3])

def countWins(n, m):
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]
    return dp[n][m]

def max_consecutive_elements(nums):
    nums.sort()
    max_count = 1
    for i in range(1, len(nums)):
        if nums[i] == nums[i-1] + 1:
            max_count += 1
        else:
            max_count = 1
    return max_count

def longest_common_prefix(arr1, arr2):
    max_len = 0
    for i in range(len(arr1)):
        for j in range(len(arr2)):
            prefix = ""
            for k in range(min(len(arr1[i]), len(arr2[j]))):
                if arr1[i][k] == arr2[j][k]:
                    prefix += arr1[i][k]
                else:
                    break
            max_len = max(max_len, len(prefix))
    return max_len

def solve(S, N):
    T = set()
    for i in range(len(S)):
        if S[i] == '?':
            T.add(int(S[:i] + '0' + S[i+1:]))
        else:
            T.add(int(S[:i] + S[i+1:]))

    for num in T:
        if num <= N:
            return num

    return -1

def max_candies(H, W, T, grid):
    from collections import deque

    # Directions for moving up, down, left, right
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Find start and goal positions
    start = None
    goal = None
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)

    # BFS to find the maximum number of candy squares
    queue = deque([(start[0], start[1], 0, 0)])  # (row, col, moves, candies)
    visited = set()
    visited.add((start[0], start[1], 0))

    while queue:
        row, col, moves, candies = queue.popleft()

        # If we reach the goal, return the number of candies
        if (row, col) == goal:
            return candies

        # If we have used up all moves, continue to the next state
        if moves >= T:
            continue

        # Explore all possible moves
        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            # Check if the new position is within bounds and not a wall
            if 0 <= new_row < H and 0 <= new_col < W and grid[new_row][new_col] != '#':
                new_candies = candies
                if grid[new_row][new_col] == 'o':
                    new_candies += 1

                # If the new position is not visited with the same number of candies, add it to the queue
                if (new_row, new_col, new_candies) not in visited:
                    visited.add((new_row, new_col, new_candies))
                    queue.append((new_row, new_col, moves + 1, new_candies))

    # If we exhaust the queue without finding the goal, return -1
    return -1

MOD = 998244353

def count_valid_strings(S):
    n = len(S)
    dp = [[0] * 53 for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(53):
            if S[i-1] == '?':
                dp[i][j] = (dp[i-1][j] + dp[i-1][j-1]) % MOD
            else:
                dp[i][j] = dp[i-1][j]

    return sum(dp[n]) % MOD

