import itertools

def can_rearrange(strings):
    N = len(strings)
    M = len(strings[0])

    def check(perm):
        for i in range(N-1):
            if perm[i] != perm[i+1]:
                for j in range(M):
                    if perm[i][j] != perm[i+1][j]:
                        return False
        return True

    for perm in itertools.permutations(strings):
        if check(perm):
            return "Yes"
    return "No"

