def max_sum_of_gifts(N, M, D, A, B):
    A.sort()
    B.sort()
    i, j = 0, 0
    max_sum = -1
    while i < N and j < M:
        if A[i] - B[j] <= D:
            max_sum = max(max_sum, A[i] + B[j])
            i += 1
        else:
            j += 1
    return max_sum

def min_time_to_make_string(X, Y, Z, S):
    # Initialize the time and the current state of the Caps Lock key
    time = 0
    caps_lock_on = False

    # Iterate through each character in the string
    for char in S:
        if char == 'a':
            # If the Caps Lock key is off, press 'a' key
            if not caps_lock_on:
                time += X
                caps_lock_on = True
            else:
