import heapq

def max_tastiness(N, courses):
    # Priority queue to store courses (negative tastiness for max-heap)
    pq = []
    # Dictionary to store maximum tastiness for healthy and upset stomachs
    healthy_tastiness = {}
    upset_tastiness = {}

    # Initialize the priority queue with all courses
    for i in range(N):
        if courses[i][0] == 0:
            heapq.heappush(pq, (-courses[i][1], courses[i][1]))
        else:
            heapq.heappush(pq, (-courses[i][1], courses[i][1]))

    total_tastiness = 0

    # Process the priority queue
    while pq:
        taste, tastiness = heapq.heappop(pq)
        taste = -taste

        if taste < 0:
            continue

        if taste in healthy_tastiness:
            healthy_tastiness[taste] = max(healthy_tastiness[taste], tastiness)
        else:
            healthy_tastiness[taste] = tastiness

        if taste in upset_tastiness:
            upset_tastiness[taste] = max(upset_tastiness[taste], tastiness)
        else:
            upset_tastiness[taste] = tastiness

        if taste == 0:
            # Eat the course
            total_tastiness += tastiness
            if taste in healthy_tastiness:
                healthy_tastiness[taste] = max(healthy_tastiness[taste], tastiness)
            else:
                healthy_tastiness[taste] = tastiness
            if taste in upset_tastiness:
                upset_tastiness[taste] = max(upset_tastiness[taste], tastiness)
            else:
                upset_tastiness[taste] = tastiness
        else:
            # Skip the course
            continue

    # If Takahashi is not dead, return the total tastiness
    if total_tastiness > 0:
        return total_tastiness
    else:
        return 0

