def nand_sum(N, S):
    f = [[0]*N for _ in range(N)]
    for i in range(N):
        f[i][i] = S[i]
    for i in range(N-1):
        for j in range(i+1, N):
            f[i][j] = f[i][j-1] & S[j]
    return sum(sum(f[i][j] for j in range(i+1, N)) for i in range(N))

