def find_cycle(N, A):
    visited = [False] * (N + 1)
    parent = [-1] * (N + 1)
    cycle = []

    def dfs(v):
        visited[v] = True
        for i in range(1, N + 1):
            if A[v - 1] == i and not visited[i]:
                parent[i] = v
                if dfs(i):
                    return True
        return False

    for i in range(1, N + 1):
        if not visited[i]:
            if dfs(i):
                cycle.append(i)
                break

    return cycle

