def count_shared_faces(N, cuboids):
    shared_faces = [0] * N

    for i in range(N):
        x1, y1, z1, x2, y2, z2 = cuboids[i]

        # Check for shared faces with the previous cuboid
        if i > 0:
            if (x1 == x2 and y1 == y2 and z1 == z2) or (x1 == x2 and y1 == y2 and z1 < z2):
                shared_faces[i] += 1

        # Check for shared faces with the next cuboid
        if i < N - 1:
            if (x1 == x2 and y1 == y2 and z1 == z2) or (x1 == x2 and y1 == y2 and z1 > z2):
                shared_faces[i] += 1

    return shared_faces

def max_happiness(N, M, items):
    pull_tab_cans = []
    regular_cans = []
    can_openers = []

    for T, X in items:
        if T == 0:
            pull_tab_cans.append(X)
        elif T == 1:
            regular_cans.append(X)
        elif T == 2:
            can_openers.append(X)

    pull_tab_cans.sort(reverse=True)
    regular_cans.sort(reverse=True)
    can_openers.sort(reverse=True)

    total_happiness = 0
    pull_tab_count = 0
    regular_count = 0
    can_openers_used = 0

    for i in range(M):
        if pull_tab_count < len(pull_tab_cans):
            total_happiness += pull_tab_cans[pull_tab_count]
            pull_tab_count += 1
        elif regular_count < len(regular_cans):
            total_happiness += regular_cans[regular_count]
            regular_count += 1
        elif can_openers_used < len(can_openers):
            total_happiness += can_openers[can_openers_used]
            can_openers_used += 1
        else:
            break

    return total_happiness

