def min_operations(N, A):
    min_val = min(A)
    max_val = max(A)
    operations = 0

    while max_val - min_val > 1:
        operations += 1
        if min_val + 1 == max_val:
            min_val += 1
            max_val -= 1
        else:
            min_val -= 1
            max_val += 1

    return operations

def count_remaining_cookies(H, W, cookies):
    # Create a 2D list to store the cookies
    cookies = [list(row) for row in cookies]

