    for i in range(H):
        if len(set(cookies[i])) > 1:
            for j in range(W):
                if cookies[i][j] == cookies[i][j+1]:
                    cookies[i][j], cookies[i][j+1] = cookies[i][j+1], cookies[i][j]

    # Mark cookies in columns
    for j in range(W):
        if len(set(cookies[i][j] for i in range(H))) > 1:
            for i in range(H):
