    for i in range(H):
        for j in range(W):
            if cookies[i][j] in cookies[i][j+1] or cookies[i][j] in cookies[i+1][j]:
                cookies[i][j], cookies[i][j+1] = cookies[i][j+1], cookies[i][j]

