def min_seconds_to_stop_reels(M, S1, S2, S3):
    # Create a dictionary to store the positions of each reel
    reel_positions = {i: [] for i in range(M)}

    # Populate the dictionary with the positions of each reel
    for i in range(M):
        reel_positions[i].append(S1[i])
        reel_positions[i].append(S2[i])
        reel_positions[i].append(S3[i])

    # Check if all reels have the same character
    if len(set(reel_positions[0])) != 1:
        return -1

    # Find the minimum time to stop all reels so that they display the same character
    min_time = float('inf')
    for i in range(M):
        for j in range(M):
            if S1[i] == S2[j] == S3[i]:
                time = (j - i) % M
                if time < min_time:
                    min_time = time

    return min_time

