def min_cost_to_achieve_goal(N, K, P, C, A):
    # Initialize the minimum cost to a large number
    min_cost = float('inf')

    # Iterate over all possible combinations of development plans
    for i in range(1, N + 1):
        for j in range(1, K + 1):
            # Calculate the cost and parameter values for the current combination
            cost = C[i - 1]
            param_values = [A[i - 1][j - 1] for j in range(K)]

            # Check if the current combination achieves the goal
            if all(param_value >= P for param_value in param_values):
                # Update the minimum cost if the current combination is cheaper
                min_cost = min(min_cost, cost)

