def find_matching_strings(N, T_prime, S_list):
    valid_indices = []

    for i in range(N):
        S_i = S_list[i]

        # Check if S_i is equal to T_prime
        if S_i == T_prime:
            valid_indices.append(i + 1)  # Convert to 1-based index

        # Check if S_i can be obtained by inserting one character
        if len(S_i) == len(T_prime) + 1:
            for j in range(len(S_i)):
                if S_i[:j] + S_i[j+1:] == T_prime:
                    valid_indices.append(i + 1)

        # Check if S_i can be obtained by deleting one character
        if len(S_i) == len(T_prime):
            for j in range(len(S_i)):
                if S_i[:j] + S_i[j+1:] == T_prime:
                    valid_indices.append(i + 1)

        # Check if S_i can be obtained by changing one character
        if len(S_i) == len(T_prime) + 1:
            for j in range(len(S_i)):
                if S_i[:j] + S_i[j+1] == T_prime:
