def min_operations(H, W, K, S):
    # Initialize the minimum operations to a large number
    min_ops = float('inf')

    # Check all possible positions for the K x K block
    for i in range(H - K + 1):
        for j in range(W - K + 1):
            # Count the number of 'o' in the K x K block
            count_o = sum(S[i + k][j:j + K] == 'o' for k in range(K))
            # If the count of 'o' is at least K, update the minimum operations
            if count_o >= K:
                min_ops = min(min_ops, K - count_o)

    # Check all possible positions for the K x K block in the first row
    for j in range(W - K + 1):
        # Count the number of 'o' in the K x K block
        count_o = sum(S[i][j + k] == 'o' for k in range(K))
        # If the count of 'o' is at least K, update the minimum operations
        if count_o >= K:
            min_ops = min(min_ops, K - count_o)

    # Check all possible positions for the K x K block in the last row
    for i in range(H - K + 1):
        # Count the number of 'o' in the K x K block
        count_o = sum(S[i + k][j] == 'o' for k in range(K))
        # If the count of 'o' is at least K, update the minimum operations
        if count_o >= K:
            min_ops = min(min_ops, K - count_o)

    # If the minimum operations is still infinity, it means it's impossible to satisfy the condition
    if min_ops == float('inf'):
        return -1
    else:
        return min_ops

