                        # If the new cell has a magnet, set the degree of freedom to 0
                        if grid[ni][nj] == '#':
                            degree_of_freedom[i][j] = 0
                        # Otherwise, set the degree of freedom to the maximum of the current cell's degree of freedom and the new cell's degree of freedom
                        else:
                            degree_of_freedom[i][j] = max(degree_of_freedom[i][j], degree_of_freedom[ni][nj])

    # Find the maximum degree of freedom among all cells without magnets
    max_degree = max(max(row) for row in degree_of_freedom)
    return max_degree

import sys
