def find_bingo_turn(N, T, A):
    # Initialize the grid
    grid = [[0]*N for _ in range(N)]

    # Mark the cells with the announced numbers
    for i in range(T):
        grid[A[i] - 1][i] = 1

    # Check rows, columns, and diagonals for Bingo
    for i in range(N):
        if all(grid[i][j] == 1 for j in range(N)):
