def sum_of_power(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= nums[i - 1]:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - nums[i - 1]]) % MOD

    return sum(dp[n]) % MOD

