        for j in range(i, len(energy)):
            current_energy += energy[j]
            if j - i >= k:
                max_energy = max(max_energy, current_energy)
                break
    return max_energy

def digit_diff(nums):
    nums.sort()
    total_diff = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            total_diff += nums[i] - nums[j]
    return total_diff

def waysToReachStair(k):
    if k == 0:
        return 2
    elif k == 1:
        return 4
    else:
        return waysToReachStair(k - 1) + waysToReachStair(k - 2)

def powerful_array(x):
    powers = []
    while x:
        powers.append(1 << (x & -x))
        x >>= 1
    return powers

def product_mod(queries):
    big_nums = []
    for i in range(1, 10**15 + 1):
        big_nums.extend(powerful_array(i))

    answer = []
    for from_i, to_i, mod_i in queries:
        product = 1
        for i in range(from_i, to_i + 1):
            product = (product * big_nums[i]) % mod_i
        answer.append(product)

    return answer

def find_occurrences(nums, queries, x):
    answer = []
    for q in queries:
        count = nums.count(x)
        if count < q:
            answer.append(-1)
        else:
            answer.append(count - q + 1)
    return answer
